import {requireVendorManager} from '@/lib/auth/vendor';import {getCuisineTypes,getVendorMedia,getVendorRestaurant} from '@/services/vendor-dashboard';import {RestaurantForm} from './restaurant-form';
export default async function RestaurantPage(){const context=await requireVendorManager();const[data,cuisines,media]=await Promise.all([getVendorRestaurant(context.restaurant!.id),getCuisineTypes(),getVendorMedia(context.userId,context.restaurant!.id)]);return <><div className="vendor-page-head"><div><p className="section-kicker">Votre établissement</p><h1>Mon restaurant</h1><p>Les informations que vos clients utilisent vraiment.</p></div></div><RestaurantForm restaurant={data.restaurant} cuisineIds={data.cuisineIds} cuisines={cuisines} media={media}/></>}
